import React, { useState } from 'react';
import { Outlet, Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
    FaHome, FaCalendarAlt, FaRoad, FaChartBar,
    FaSignOutAlt, FaUser, FaBars, FaTimes
} from 'react-icons/fa';

const Layout = () => {
    const { user, logout } = useAuth();
    const location = useLocation();
    const navigate = useNavigate();
    const [sidebarOpen, setSidebarOpen] = useState(false);

    const navigation = [
        { name: 'Dashboard', href: '/dashboard', icon: FaHome },
        { name: 'Daily Tracker', href: '/tracker', icon: FaCalendarAlt },
        { name: 'Roadmap', href: '/weekly-focus', icon: FaRoad },
        { name: 'Progress', href: '/progress', icon: FaChartBar },
    ];

    const handleLogout = () => {
        logout();
        navigate('/login');
    };

    return (
        <div className="min-h-screen bg-[#f5f7fb] d-flex">
            {/* Mobile Sidebar */}
            {sidebarOpen && (
                <div className="fixed inset-0 z-50 d-lg-none">
                    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setSidebarOpen(false)} />
                    <div className="fixed inset-y-0 left-0 w-72 bg-white shadow-2xl p-4">
                        <div className="d-flex justify-content-between align-items-center mb-4 pb-3 border-bottom">
                            <span className="fw-bold fs-4" style={{ background: 'linear-gradient(135deg, #6366F1, #8B5CF6)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                                🚀 RoadMap
                            </span>
                            <button onClick={() => setSidebarOpen(false)} className="btn btn-link text-dark p-0">
                                <FaTimes size={20} />
                            </button>
                        </div>
                        <nav className="d-flex flex-column gap-1">
                            {navigation.map((item) => {
                                const isActive = location.pathname === item.href;
                                return (
                                    <Link
                                        key={item.name}
                                        to={item.href}
                                        onClick={() => setSidebarOpen(false)}
                                        className={`sidebar-link ${isActive ? 'active' : ''}`}
                                    >
                                        <item.icon size={18} />
                                        {item.name}
                                    </Link>
                                );
                            })}
                            <hr className="my-3" />
                            <button onClick={handleLogout} className="sidebar-link text-danger">
                                <FaSignOutAlt size={18} /> Logout
                            </button>
                        </nav>
                    </div>
                </div>
            )}

            {/* Desktop Sidebar */}
            <div className="d-none d-lg-flex flex-column vh-100 bg-white shadow-sm p-4" style={{ width: '260px', position: 'fixed', zIndex: 100 }}>
                <div className="mb-4 pb-3 border-bottom">
                    <span className="fw-bold fs-4" style={{ background: 'linear-gradient(135deg, #6366F1, #8B5CF6)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                        🚀 RoadMap
                    </span>
                </div>
                <nav className="d-flex flex-column gap-1 flex-grow-1">
                    {navigation.map((item) => {
                        const isActive = location.pathname === item.href;
                        return (
                            <Link key={item.name} to={item.href} className={`sidebar-link ${isActive ? 'active' : ''}`}>
                                <item.icon size={18} /> {item.name}
                            </Link>
                        );
                    })}
                </nav>
                <div className="border-top pt-3">
                    <div className="d-flex align-items-center gap-3 p-2 rounded-3 bg-light mb-2">
                        <div className="bg-gradient-to-r from-indigo-500 to-purple-600 text-white rounded-circle d-flex align-items-center justify-content-center" style={{ width: 36, height: 36 }}>
                            <FaUser size={16} />
                        </div>
                        <div className="flex-grow-1">
                            <p className="fw-semibold mb-0 small">{user?.fullName || user?.username}</p>
                            <p className="text-muted small mb-0">{user?.email}</p>
                        </div>
                    </div>
                    <button onClick={handleLogout} className="sidebar-link text-danger w-100">
                        <FaSignOutAlt size={18} /> Logout
                    </button>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-grow-1" style={{ marginLeft: '260px' }}>
                <div className="d-lg-none sticky-top bg-white/80 backdrop-blur-sm p-3 border-bottom" style={{ zIndex: 50 }}>
                    <button onClick={() => setSidebarOpen(true)} className="btn btn-link text-dark p-0">
                        <FaBars size={24} />
                    </button>
                    <span className="ms-3 fw-bold" style={{ background: 'linear-gradient(135deg, #6366F1, #8B5CF6)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                        🚀 RoadMap
                    </span>
                </div>
                <main className="p-4 p-md-5">
                    <Outlet />
                </main>
            </div>
        </div>
    );
};

export default Layout;
